import type { AISuggestionListProps, AISuggestionProps } from "./ai-suggestion.types";

import { type CSSObject } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// --- AISuggestionList ---

// Make sure component name matches its type in the ThemeComponentVariants
const suggestionListComponentName = "AISuggestionList";

// Generate child element class names for the component, should match available style slots
export const AISuggestionListClasses = {
  root: "exp-textura_ai_suggestion-list",
  label: "exp-textura_ai_suggestion-list_label",
};

const generateSuggestionListStyles = (props: AISuggestionListProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AISuggestionListProps["styleSlots"]>(
        suggestionListComponentName,
        theme,
        variant,
        styleSlotsProp,
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[8]),
    width: "100%",
    paddingTop: theme.toRem(theme.spacing[16]),

    [`.${AISuggestionListClasses.label}`]: {
      ...theme.typography.body.mdEmphasis, // Bold 14px
      color: theme.color.content.default,
      marginBottom: 0,
      ...styleSlots?.label,
    },

    ...styleSlots?.root,
  };
};

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAISuggestionList = styled("div", {
  shouldForwardProp: (prop) => !getExcludedDOMProps().includes(prop),
})<AISuggestionListProps>((props) => generateSuggestionListStyles(props));

// --- AISuggestion ---

// Make sure component name matches its type in the ThemeComponentVariants
const suggestionComponentName = "AISuggestion";

// Generate child element class names for the component, should match available style slots
export const AISuggestionClasses = {
  root: "exp-textura_ai_suggestion",
};

const generateSuggestionStyles = (props: AISuggestionProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AISuggestionProps["styleSlots"]>(
        suggestionComponentName,
        theme,
        variant,
        styleSlotsProp,
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    alignItems: "center",
    width: "100%",
    gap: theme.toRem(theme.spacing[8]),
    padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[8])}`,
    marginInlineStart: `calc(${theme.toRem(theme.spacing[8])} * -1)`,
    borderRadius: theme.toRem(theme.border.radius.sm),
    backgroundColor: "transparent",
    border: "none",
    cursor: "pointer",
    textAlign: "left",
    textDecoration: "none",
    color: theme.color.content.default,
    ...theme.typography.body.md,

    "&:hover:not(:disabled)": {
      backgroundColor: theme.color.background.defaultHover,
      color: theme.color.content.strong,
      "& > svg": {
        color: theme.color.content.iconStrong,
        ...styleSlots?.iconHover,
      },
      ...styleSlots?.hover,
    },
    "&:active:not(:disabled)": {
      backgroundColor: theme.color.background.defaultPressed,
    },
    "&:disabled": {
      opacity: 0.5,
      cursor: "not-allowed",
      ...styleSlots?.disabled,
    },

    "&[data-loading='true']": {
      opacity: 1,
      cursor: "default",
      pointerEvents: "none",
      userSelect: "none",
      backgroundColor: "transparent",
      ...styleSlots?.loading,
    },

    "& > svg": {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      width: theme.toRem(16),
      height: theme.toRem(16),
      color: theme.color.content.icon,
      ...styleSlots?.icon,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedSuggestionDOMProps = [...getExcludedDOMProps(), "type"];

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAISuggestion = styled("button", {
  shouldForwardProp: (prop) => !excludedSuggestionDOMProps.includes(prop),
})<AISuggestionProps>((props) => generateSuggestionStyles(props));
